@Configuration
class PubSubConfig {
    @Bean
    RedisMessageListenerContainer kontener(RedisConnectionFactory cf, Odbiorca odbiorca) {
        RedisMessageListenerContainer c = new RedisMessageListenerContainer();
        c.setConnectionFactory(cf);
        c.addMessageListener(odbiorca, new ChannelTopic("ui-odswiez"));
        c.addMessageListener(odbiorca, new PatternTopic("zamowienia.*"));
        return c;
    }
}

@Component
class Odbiorca implements MessageListener {
    public void onMessage(Message m, byte[] wzorzec) {
        System.out.println(new String(m.getChannel()) + ": " + new String(m.getBody(), StandardCharsets.UTF_8));
    }
}

@Service
class Nadawca {
    private final StringRedisTemplate redis;
    Nadawca(StringRedisTemplate redis) { this.redis = redis; }
    void odswiezPanel() { redis.convertAndSend("ui-odswiez", "nowe-zamowienie"); }
}
ChannelTopic = SUBSCRIBE dokładnie jednego kanału; PatternTopic = PSUBSCRIBE z wzorcem (zamowienia.* obejmie zamowienia.nowe, zamowienia.anulowane). Przy wzorcu parametr 'wzorzec' w onMessage zawiera pasujący wzorzec.

import java.util.*;
import java.util.concurrent.CopyOnWriteArrayList;
import java.util.function.Consumer;

public class PubSubVsStream {
    static class Kanal {
        final List<Consumer<String>> subskrybenci = new CopyOnWriteArrayList<>();
        int publish(String w) { subskrybenci.forEach(s -> s.accept(w)); return subskrybenci.size(); }
    }
    static class Strumien {
        final List<String> wpisy = new ArrayList<>();
        void xadd(String w) { wpisy.add(w); }
        List<String> czytajOd(int pozycja) { return wpisy.subList(pozycja, wpisy.size()); }
    }

    public static void main(String[] args) {
        Kanal k = new Kanal();
        List<String> odebrane = new ArrayList<>();
        System.out.println(k.publish("test1"));   // 0
        Consumer<String> sub = odebrane::add;
        k.subskrybenci.add(sub);
        System.out.println(k.publish("test2"));   // 1
        k.subskrybenci.remove(sub);
        System.out.println(k.publish("test3"));   // 0
        System.out.println("Pub/Sub odebral: " + odebrane);  // [test2]

        Strumien s = new Strumien();
        s.xadd("test1"); s.xadd("test2"); s.xadd("test3");
        System.out.println("Spozniony czytelnik strumienia: " + s.czytajOd(0)); // [test1, test2, test3]
    }
}

